SELECT COUNT(DISTINCT ce.cabineqref) FROM cabinenvironment ce 
WHERE CAST(ce.cabinclimate->>'temperature_c' AS numeric) BETWEEN 18 AND 24
  AND CAST(ce.cabinclimate->>'o2_percent' AS numeric) > 19.5;
